CREATE DATABASE IF NOT EXISTS news_portal CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE news_portal;
CREATE TABLE IF NOT EXISTS users(id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS news_articles(id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,category VARCHAR(50) NOT NULL,description TEXT NOT NULL,image VARCHAR(255),content TEXT,created_at DATE NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS article_submissions(id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120) NOT NULL,category VARCHAR(100) NOT NULL,author VARCHAR(60) NOT NULL,image_url TEXT,content TEXT NOT NULL,status ENUM('Pending','Approved','Rejected') DEFAULT 'Pending',submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bookmarks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,article_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unique_user_article(user_id,article_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS subscriptions(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,category VARCHAR(20) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY user_category(user_id,category),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS help_questions(id INT AUTO_INCREMENT PRIMARY KEY,question TEXT NOT NULL,submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS submission_owners(submission_id INT PRIMARY KEY,user_id INT NOT NULL,linked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(submission_id) REFERENCES article_submissions(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS article_comments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,article_id INT NOT NULL,user_id INT NOT NULL,parent_id BIGINT UNSIGNED NULL,body TEXT NOT NULL,status ENUM('Pending','Approved','Hidden') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(article_id) REFERENCES news_articles(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,link_url VARCHAR(255),is_read TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
-- Existing tables are retained; no DROP/DELETE/TRUNCATE commands.
SHOW TABLES;
